module MB_wrapper
   (reset,
    sys_clock_0,
    usb_uart_rxd,
    usb_uart_txd);
  input reset;
  input sys_clock_0;
  input usb_uart_rxd;
  output usb_uart_txd;

  wire reset;
  wire reset_IBUF;
  (* IBUF_LOW_PWR *) wire sys_clock_0;
  wire usb_uart_rxd;
  wire usb_uart_rxd_IBUF;
  wire usb_uart_txd;
  wire usb_uart_txd_OBUF;

  (* HW_HANDOFF = "MB.hwdef" *) 
  MB MB_i
       (.reset(reset_IBUF),
        .sys_clock_0(sys_clock_0),
        .usb_uart_rxd(usb_uart_rxd_IBUF),
        .usb_uart_txd(usb_uart_txd_OBUF));
  IBUF reset_IBUF_inst
       (.I(reset),
        .O(reset_IBUF));
  IBUF usb_uart_rxd_IBUF_inst
       (.I(usb_uart_rxd),
        .O(usb_uart_rxd_IBUF));
  OBUF usb_uart_txd_OBUF_inst
       (.I(usb_uart_txd_OBUF),
        .O(usb_uart_txd));
endmodule

